// Borrowed/modified from https://github.com/jenseng/abuse-the-platform/blob/2993a7e846c95ace693ce61626fa072174c8d9c7/app/utils/singleton.ts

type RememberStore = Map<string, unknown>

const STORE_KEY = '__remember_epic_web'

function getStore(): RememberStore {
	const thusly = globalThis as typeof globalThis & {
		[STORE_KEY]?: RememberStore
	}
	thusly[STORE_KEY] ??= new Map()
	return thusly[STORE_KEY]
}

/**
 * Remembers and retrieves a value by a given name, or the value generated by
 * `getValue` if the name doesn't exist. The return type is inferred from the
 * return type of `getValue`.
 *
 * Values live on `globalThis`, so they survive module re-imports (for example
 * during development HMR) and are created once per process.
 */
export function remember<Value>(name: string, getValue: () => Value): Value {
	const store = getStore()
	if (!store.has(name)) {
		store.set(name, getValue())
	}
	return store.get(name) as Value
}

/**
 * Forgets a remembered value by a given name. Does not throw if the name
 * doesn't exist.
 *
 * @returns whether a remembered value existed and has been forgotten
 */
export function forget(name: string): boolean {
	return getStore().delete(name)
}
